-- Revisión 09:47 del 23-11 (c): shows nuevos desde el 21 con alguna venta futura y su ficha (solo metadatos)
SELECT a.name, COALESCE(f.tier, 1) AS tier, s.country, (SELECT status FROM sheet WHERE artist_id = a.id) AS ficha, COUNT(DISTINCT s.source_id) AS shows, MIN(json_extract(j.value, '$.startsAt')) AS proxima, s.is_package FROM show s JOIN artist a ON a.id = s.artist_id LEFT JOIN follow f ON f.artist_id = a.id, json_each(s.snapshot_json, '$.sales') j WHERE s.first_seen_at >= '2026-11-21T00:00:00Z' AND json_extract(j.value, '$.startsAt') > '2026-11-23T09:00:00Z' GROUP BY a.id, s.country, s.is_package ORDER BY proxima LIMIT 40;
